import {FormEvent,useEffect,useState} from 'react';
import {useQuery,useQueryClient} from '@tanstack/react-query';
import {useNavigate} from 'react-router-dom';
import {api,apiForm,login} from './api';
import {ConfirmButton,ErrorPanel,Header,JsonView,Loading,Modal,StatusBadge,Table,useFormError} from './components';

export {WorkflowEditorPage} from './workflow-editor';
export {WorkflowTransferPage} from './workflow-transfer';

function parseEndpointBody(value:any){try{return value?JSON.parse(String(value)):{} }catch{return {}}}

export function LoginPage({onLogin}:{onLogin:()=>void}){
  const navigate=useNavigate();
  const [email,setEmail]=useState('admin@parser.local');
  const [password,setPassword]=useState('');
  const [error,setError]=useState('');
  async function submit(event:FormEvent){event.preventDefault();try{await login(email,password);onLogin();navigate('/',{replace:true})}catch(value){setError(value instanceof Error?value.message:String(value))}}
  return <div className="login"><form onSubmit={submit}><h1>Parser Studio</h1><p>Self-hosted no-code сбор данных</p><label>Email<input value={email} onChange={event=>setEmail(event.target.value)}/></label><label>Пароль<input type="password" value={password} onChange={event=>setPassword(event.target.value)}/></label>{error&&<div className="error">{error}</div>}<button>Войти</button></form></div>;
}

export function DashboardPage(){
  const query=useQuery({queryKey:['dashboard'],queryFn:()=>api<any>('/dashboard'),refetchInterval:15000});
  const workflows=useQuery({queryKey:['workflows'],queryFn:()=>api<any[]>('/workflows')});
  if(query.isLoading)return <Loading/>;if(query.error)return <ErrorPanel error={query.error}/>;
  const data=query.data||{};
  const workflowNames=Object.fromEntries((workflows.data||[]).map(item=>[item.id,item.name]));
  const latestRuns=(data.latest_runs||[]).map((run:any)=>({...run,workflow_name:workflowNames[run.workflow_id]||run.workflow_id}));
  return <><Header title="Главная"/><div className="cards">{[['Активные источники',data.active_sources],['Активные workflows',data.active_workflows],['Запуски',data.runs],['Ошибки',data.failed_runs],['Ожидают проверки',data.review_pending]].map(([label,value])=><div className="card" key={String(label)}><span>{label}</span><strong>{value??0}</strong></div>)}</div><div className="split"><div className="panel"><h2>Последние запуски</h2><Table rows={latestRuns} columns={['status','workflow_name','created_at']}/></div><div className="panel"><h2>Состояние системы</h2><div className="metric-list"><div><span>Успешные за 24 часа</span><strong>{data.success_runs_24h??0}</strong></div><div><span>Изменения</span><strong>{data.changed_records??0}</strong></div><div><span>LLM-вызовы</span><strong>{data.llm_calls??0}</strong></div></div></div></div></>;
}

export function ProjectsPage(){
  const qc=useQueryClient();const query=useQuery({queryKey:['projects'],queryFn:()=>api<any[]>('/projects')});const [open,setOpen]=useState(false);const {error,wrap}=useFormError();
  async function create(event:FormEvent<HTMLFormElement>){const form=new FormData(event.currentTarget);await api('/projects',{method:'POST',body:JSON.stringify({name:form.get('name'),slug:form.get('slug'),description:form.get('description'),template:form.get('template'),default_timezone:form.get('default_timezone'),default_locale:form.get('default_locale')})});setOpen(false);await qc.invalidateQueries({queryKey:['projects']})}
  return <><Header title="Проекты" actions={<button onClick={()=>setOpen(true)}>Создать проект</button>}/><div className="panel">{query.isLoading?<Loading/>:<Table rows={query.data||[]} columns={['name','slug','status','default_timezone','created_at']}/>}</div>{open&&<Modal title="Новый проект" onClose={()=>setOpen(false)}><form onSubmit={wrap(create)} className="form"><label>Название<input name="name" required/></label><label>Slug<input name="slug" required pattern="[a-z0-9-]+"/></label><div className="split"><label>Часовой пояс<input name="default_timezone" defaultValue="Europe/Minsk" required/></label><label>Язык<select name="default_locale" defaultValue="ru-BY"><option value="ru-BY">Русский</option><option value="be-BY">Белорусский</option><option value="en-US">English</option></select></label></div><label>Описание<textarea name="description"/></label><label>Шаблон<select name="template"><option value="blank">Пустой проект</option><option value="bank_deposits">Мониторинг банковских депозитов</option></select></label>{error&&<div className="error">{error}</div>}<button>Создать</button></form></Modal>}</>;
}

export function SourcesPage(){
  const qc=useQueryClient();
  const projects=useQuery({queryKey:['projects'],queryFn:()=>api<any[]>('/projects')});
  const sources=useQuery({queryKey:['sources'],queryFn:()=>api<any[]>('/sources')});
  const restoredDraft=JSON.parse(sessionStorage.getItem('source_wizard_draft')||'{}');
  const [wizard,setWizard]=useState(false);const [documentOpen,setDocumentOpen]=useState(false);const [accessOpen,setAccessOpen]=useState(false);const [editing,setEditing]=useState<any>(null);const [projectFilter,setProjectFilter]=useState('');const [profile,setProfile]=useState<any>(restoredDraft.profile||null);const [documentPreview,setDocumentPreview]=useState<any>(null);const [url,setUrl]=useState(restoredDraft.url||'');const [loading,setLoading]=useState(false);const [error,setError]=useState('');
  useEffect(()=>{if(wizard)sessionStorage.setItem('source_wizard_draft',JSON.stringify({url,profile}));},[wizard,url,profile]);
  async function analyze(){setLoading(true);setError('');try{setProfile(await api('/sources/profile',{method:'POST',body:JSON.stringify({url})}))}catch(value){setError(value instanceof Error?value.message:String(value))}finally{setLoading(false)}}
  async function create(event:FormEvent<HTMLFormElement>){
    event.preventDefault();const form=new FormData(event.currentTarget);const endpoint=JSON.parse(sessionStorage.getItem('source_endpoint')||'null');setLoading(true);
    try{
      await api<any>('/sources',{method:'POST',body:JSON.stringify({project_id:form.get('project_id'),name:form.get('name'),entry_url:endpoint?.url||url,source_type:endpoint?'JSON_API':profile?.document_type?'PDF_DOCUMENT':'WEB_PAGE',fetch_mode:endpoint?'XHR_JSON':form.get('fetch_mode'),settings:{timeout:45,profile:profile||{},http_request:endpoint?{url:endpoint.url,method:endpoint.method,headers:endpoint.headers||{},query_params:endpoint.query_params||{},json_body:parseEndpointBody(endpoint.request_body)}:{}}})});
      sessionStorage.removeItem('source_wizard_draft');sessionStorage.removeItem('source_endpoint');setWizard(false);await qc.invalidateQueries({queryKey:['sources']})
    }catch(value){setError(value instanceof Error?value.message:String(value))}finally{setLoading(false)}
  }
  async function previewDocument(file:File){setLoading(true);setError('');try{const data=new FormData();data.set('file',file);setDocumentPreview(await apiForm('/documents/parse',data))}catch(value){setError(value instanceof Error?value.message:String(value))}finally{setLoading(false)}}
  async function uploadDocument(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);const file=form.get('file');if(!(file instanceof File)||!file.size){setError('Выберите файл');return}setLoading(true);setError('');try{await apiForm<any>('/documents/upload-source',form);setDocumentOpen(false);await qc.invalidateQueries({queryKey:['sources']})}catch(value){setError(value instanceof Error?value.message:String(value))}finally{setLoading(false)}}
  async function saveAccess(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);await api(`/sources/${form.get('source_id')}/access`,{method:'PATCH',body:JSON.stringify({access_status:form.get('access_status'),access_note:form.get('access_note')})});setAccessOpen(false);await qc.invalidateQueries({queryKey:['sources']})}
  async function saveSource(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);await api(`/sources/${editing.id}`,{method:'PATCH',body:JSON.stringify({name:form.get('name'),entry_url:form.get('entry_url'),fetch_mode:form.get('fetch_mode'),enabled:form.get('enabled')==='on',description:form.get('description')})});setEditing(null);await qc.invalidateQueries({queryKey:['sources']})}
  const sourceRows=(sources.data||[]).filter(source=>!projectFilter||source.project_id===projectFilter).map(source=>({...source,access_status:source.settings?.access_status||'PUBLIC'}));
  return <><Header title="Источники" subtitle="Единый каталог: добавляйте, включайте и проверяйте источники. Workflow к URL не привязан." actions={<div className="toolbar"><select value={projectFilter} onChange={event=>setProjectFilter(event.target.value)}><option value="">Все проекты</option>{projects.data?.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</select><button className="secondary" onClick={()=>setAccessOpen(true)}>Статус доступа</button><button className="secondary" onClick={()=>{setDocumentOpen(true);setDocumentPreview(null);setError('')}}>Загрузить документ</button><button onClick={()=>{setWizard(true);setProfile(null);setUrl('');setError('')}}>Добавить URL</button></div>}/><div className="panel"><Table rows={sourceRows} columns={['name','source_type','entry_url','fetch_mode','access_status','enabled','updated_at']} onRowClick={source=>setEditing(source)}/></div>{editing&&<Modal title="Настройки источника" onClose={()=>setEditing(null)}><form className="form" onSubmit={saveSource}><label>Название<input name="name" defaultValue={editing.name} required/></label><label>URL<input name="entry_url" defaultValue={editing.entry_url} required/></label><label>Режим загрузки<select name="fetch_mode" defaultValue={editing.fetch_mode}><option value="HTTP">HTTP</option><option value="PLAYWRIGHT">Playwright</option><option value="XHR_JSON">JSON/XHR</option><option value="DOCUMENT">Document parser</option></select></label><label>Описание<textarea name="description" defaultValue={editing.description}/></label><label className="checkbox"><input name="enabled" type="checkbox" defaultChecked={editing.enabled}/><span>Использовать в общем запуске</span></label><button>Сохранить источник</button></form></Modal>}{accessOpen&&<Modal title="Статус доступа источника" onClose={()=>setAccessOpen(false)}><form className="form" onSubmit={saveAccess}><label>Источник<select name="source_id" required>{sources.data?.map(source=><option key={source.id} value={source.id}>{source.name}</option>)}</select></label><label>Статус<select name="access_status" defaultValue="NEEDS_ACCESS"><option value="PUBLIC">Публичный доступ</option><option value="NEEDS_ACCESS">Нужен доступ</option><option value="UNAVAILABLE">Недоступен извне</option></select></label><label>Комментарий<textarea name="access_note" placeholder="Например: условия доступны только после входа в личный кабинет"/></label><button>Сохранить статус</button></form></Modal>}{wizard&&<Modal title="Мастер источника" wide onClose={()=>setWizard(false)}>{!profile?<div className="wizard"><div className="steps"><span className="active">1. URL и анализ</span><span>2. Режим</span><span>3. Каталог источников</span></div><div className="form"><label>URL<input value={url} placeholder="https://bank.example/rates" onChange={event=>setUrl(event.target.value)} required/></label>{error&&<div className="error">{error}</div>}<button disabled={!url||loading} onClick={analyze}>{loading?'Анализируется…':'Запустить Source Profiler'}</button></div></div>:<form className="wizard" onSubmit={create}><div className="steps"><span>1. URL</span><span className="active">2. Режим и создание</span><span>3. Готово</span></div><div className="split"><div className="form"><label>Проект<select name="project_id" required>{projects.data?.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</select></label><label>Название<input name="name" defaultValue={new URL(url).hostname} required/></label><label>Режим загрузки<select name="fetch_mode" defaultValue={profile.recommended_fetch_mode==='XHR_JSON'?'HTTP':profile.recommended_fetch_mode}><option value="HTTP">HTTP</option><option value="PLAYWRIGHT">Playwright</option><option value="DOCUMENT">Document parser</option></select></label><p className="muted">Источник появится в общем каталоге и сразу будет доступен универсальному workflow этого проекта.</p><button disabled={loading}>{loading?'Создание…':'Создать источник'}</button>{error&&<div className="error">{error}</div>}</div><SourceProfileSummary profile={profile}/></div></form>}</Modal>}{documentOpen&&<Modal title="Документ как источник" wide onClose={()=>setDocumentOpen(false)}><form className="form" onSubmit={uploadDocument}><div className="split"><label>Проект<select name="project_id" required>{projects.data?.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</select></label><label>Название источника<input name="name" required placeholder="Например, Тарифы банка за июль"/></label></div><label>Файл<input name="file" type="file" accept=".pdf,.docx,.xlsx,.csv,.json" required onChange={event=>{const file=event.target.files?.[0];if(file)void previewDocument(file)}}/></label><p className="muted">Поддерживаются PDF, DOCX, XLSX, CSV и JSON до 100 МБ. Файл сохраняется как raw artifact; отдельный workflow не создаётся.</p>{error&&<div className="error">{error}</div>}{documentPreview&&<details open><summary>Предпросмотр разбора</summary><JsonView value={documentPreview}/></details>}<button disabled={loading}>{loading?'Загрузка…':'Создать источник'}</button></form></Modal>}</>;
}

function SourceProfileSummary({profile,onEndpoint}:{profile:any;onEndpoint?:(candidate:any)=>void}){
  const modeLabels:Record<string,string>={HTTP:'HTTP — статическая страница',PLAYWRIGHT:'Playwright — JavaScript-страница',XHR_JSON:'JSON/XHR API',DOCUMENT:'Document parser'};
  function useEndpoint(item:any){sessionStorage.setItem('source_endpoint',JSON.stringify(item));onEndpoint?.(item)}
  return <div className="profile-summary"><div className="inline spread"><div><span className="eyebrow">Результат Source Profiler</span><h3>{modeLabels[profile.recommended_fetch_mode]||profile.recommended_fetch_mode}</h3></div><StatusBadge value={profile.http_status?`HTTP ${profile.http_status}`:'ANALYZED'}/></div><div className="profile-metrics"><span>Таблицы <strong>{profile.detected_tables||0}</strong></span><span>Карточки <strong>{profile.repeating_candidates?.length||0}</strong></span><span>XHR/JSON <strong>{profile.xhr_candidates?.length||0}</strong></span></div>{profile.xhr_candidates?.length>0&&<div className="table-wrap"><table><thead><tr><th>URL</th><th>Method</th><th>Status</th><th>Content type</th><th>Размер</th><th>Preview JSON</th><th>Query params</th><th>Request body</th><th>Headers</th><th/></tr></thead><tbody>{profile.xhr_candidates.map((item:any,index:number)=><tr key={`${item.url}-${index}`}><td><code>{item.url}</code></td><td>{item.method}</td><td>{item.status}</td><td>{item.content_type}</td><td>{item.size}</td><td><code>{JSON.stringify(item.preview_json).slice(0,180)}</code></td><td><code>{JSON.stringify(item.query_params)}</code></td><td><code>{String(item.request_body).slice(0,80)}</code></td><td><code>{JSON.stringify(item.headers).slice(0,120)}</code></td><td><button type="button" onClick={()=>useEndpoint(item)}>Использовать endpoint</button></td></tr>)}</tbody></table></div>}<details><summary>Полная диагностика</summary><JsonView value={profile}/></details></div>
}

export function WorkflowsPage(){
  const navigate=useNavigate();const qc=useQueryClient();const query=useQuery({queryKey:['workflows'],queryFn:()=>api<any[]>('/workflows')});const projects=useQuery({queryKey:['projects'],queryFn:()=>api<any[]>('/projects')});const [open,setOpen]=useState(false);const {error,wrap}=useFormError();
  async function create(event:FormEvent<HTMLFormElement>){const form=new FormData(event.currentTarget);const item=await api<any>('/workflows',{method:'POST',body:JSON.stringify({project_id:form.get('project_id'),name:form.get('name'),description:form.get('description'),graph_json:{version:1,settings:{},nodes:[{id:'trigger',type:'manual_trigger',position:{x:80,y:160},config:{}}],edges:[]}})});setOpen(false);await qc.invalidateQueries({queryKey:['workflows']});navigate(`/workflows/${item.id}`)}
  return <><Header title="Workflows" actions={<button onClick={()=>setOpen(true)}>Создать workflow</button>}/><div className="panel"><div className="table-wrap"><table><thead><tr><th>Название</th><th>Версия</th><th>Опубликовано</th><th>Статус</th><th></th></tr></thead><tbody>{query.data?.map(item=><tr key={item.id}><td>{item.name}</td><td>{item.version}</td><td>{item.published_version??'—'}</td><td><StatusBadge value={item.is_active?'ACTIVE':'DISABLED'}/></td><td><button onClick={()=>navigate(`/workflows/${item.id}`)}>Открыть</button></td></tr>)}</tbody></table></div></div>{open&&<Modal title="Новый workflow" onClose={()=>setOpen(false)}><form className="form" onSubmit={wrap(create)}><label>Проект<select name="project_id" required>{projects.data?.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</select></label><label>Название<input name="name" required/></label><label>Описание<textarea name="description"/></label>{error&&<div className="error">{error}</div>}<button>Создать</button></form></Modal>}</>;
}

export function WorkflowTemplatesPage(){
  const navigate=useNavigate();const qc=useQueryClient();const projects=useQuery({queryKey:['projects'],queryFn:()=>api<any[]>('/projects')});const sources=useQuery({queryKey:['sources'],queryFn:()=>api<any[]>('/sources')});const datasets=useQuery({queryKey:['datasets'],queryFn:()=>api<any[]>('/datasets')});const [projectId,setProjectId]=useState('');const templates=useQuery({queryKey:['workflow-templates',projectId],queryFn:()=>api<any[]>(`/workflow-templates${projectId?`?project_id=${projectId}`:''}`)});const workflows=useQuery({queryKey:['workflows',projectId],queryFn:()=>api<any[]>(`/workflows${projectId?`?project_id=${projectId}`:''}`)});const [creating,setCreating]=useState(false);const [saving,setSaving]=useState(false);const [instantiating,setInstantiating]=useState<any>(null);const [instantiationProjectId,setInstantiationProjectId]=useState('');const [editing,setEditing]=useState<any>(null);const {error,setError,wrap}=useFormError();
  const blankGraph={version:1,settings:{},nodes:[{id:'trigger',type:'manual_trigger',position:{x:80,y:160},config:{}}],edges:[]};
  async function createTemplate(event:FormEvent<HTMLFormElement>){const form=new FormData(event.currentTarget);await api('/workflow-templates',{method:'POST',body:JSON.stringify({project_id:form.get('project_id'),name:form.get('name'),description:form.get('description'),tags:String(form.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean),graph_json:blankGraph})});setCreating(false);await qc.invalidateQueries({queryKey:['workflow-templates']})}
  async function saveWorkflow(event:FormEvent<HTMLFormElement>){const form=new FormData(event.currentTarget);await api(`/workflow-templates/from-workflow/${form.get('workflow_id')}`,{method:'POST',body:JSON.stringify({project_id:form.get('project_id'),name:form.get('name'),description:form.get('description'),tags:String(form.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean)})});setSaving(false);await qc.invalidateQueries({queryKey:['workflow-templates']})}
  async function instantiate(event:FormEvent<HTMLFormElement>){const form=new FormData(event.currentTarget);const workflow=await api<any>(`/workflow-templates/${instantiating.id}/instantiate`,{method:'POST',body:JSON.stringify({project_id:form.get('project_id'),name:form.get('name')||null,source_id:form.get('source_id')||null,dataset_id:form.get('dataset_id')||null})});await qc.invalidateQueries({queryKey:['workflows']});navigate(`/workflows/${workflow.id}`)}
  async function updateTemplate(event:FormEvent<HTMLFormElement>){const form=new FormData(event.currentTarget);await api(`/workflow-templates/${editing.id}`,{method:'PATCH',body:JSON.stringify({name:form.get('name'),description:form.get('description'),tags:String(form.get('tags')||'').split(',').map(x=>x.trim()).filter(Boolean)})});setEditing(null);await qc.invalidateQueries({queryKey:['workflow-templates']})}
  async function removeTemplate(item:any){await api(`/workflow-templates/${item.id}`,{method:'DELETE'});await qc.invalidateQueries({queryKey:['workflow-templates']})}
  return <><Header title="Шаблоны workflow" subtitle="Шаблон — независимый снимок универсальной схемы. Источник и dataset выбираются только в созданной копии." actions={<div className="toolbar"><select value={projectId} onChange={event=>setProjectId(event.target.value)}><option value="">Все проекты</option>{projects.data?.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</select><button className="secondary" onClick={()=>{setSaving(true);setError('')}}>Сохранить workflow как шаблон</button><button onClick={()=>{setCreating(true);setError('')}}>Пустой шаблон</button></div>}/><div className="help-box"><strong>Все шаблоны должны быть универсальными:</strong> literal URL, source ID, dataset ID и site-specific схемы автоматически очищаются или отклоняются. Создайте копию системного шаблона, выберите источник и dataset уже внутри workflow.</div><div className="cards">{templates.data?.map(item=><div className="card" key={item.id}><div className="inline spread"><strong>{item.name}</strong><StatusBadge value={item.is_system?'ВСТРОЕННЫЙ':'МОЙ ШАБЛОН'}/></div><p className="muted">{item.description||'Без описания'}</p><small>{(item.tags||[]).join(' · ')||'без тегов'}</small><div className="inline"><button onClick={()=>{setInstantiating(item);setInstantiationProjectId(projectId||item.project_id||projects.data?.[0]?.id||'');setError('')}}>Создать workflow</button>{!item.is_system&&<><button className="secondary" onClick={()=>setEditing(item)}>Изменить</button><ConfirmButton className="danger" onConfirm={()=>removeTemplate(item)}>Удалить</ConfirmButton></>}</div></div>)}</div>{templates.isLoading&&<Loading/>}{templates.error&&<ErrorPanel error={templates.error}/>} {creating&&<Modal title="Новый пустой шаблон" onClose={()=>setCreating(false)}><form className="form" onSubmit={wrap(createTemplate)}><label>Проект<select name="project_id" defaultValue={projectId} required>{projects.data?.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</select></label><label>Название<input name="name" required/></label><label>Описание<textarea name="description"/></label><label>Теги через запятую<input name="tags" placeholder="web, rates"/></label><p className="muted">Создаётся универсальная заготовка с ручным триггером.</p>{error&&<div className="error">{error}</div>}<button>Создать шаблон</button></form></Modal>}{saving&&<Modal title="Сохранить workflow как шаблон" onClose={()=>setSaving(false)}><form className="form" onSubmit={wrap(saveWorkflow)}><label>Проект<select name="project_id" defaultValue={projectId} required>{projects.data?.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</select></label><label>Workflow<select name="workflow_id" required>{workflows.data?.map(workflow=><option key={workflow.id} value={workflow.id}>{workflow.name}</option>)}</select></label><label>Название шаблона<input name="name" required placeholder="Например, Универсальный web-парсер"/></label><label>Описание<textarea name="description"/></label><label>Теги через запятую<input name="tags" placeholder="web, parser"/></label><p className="muted">Источник и dataset не копируются; site-specific настройки очищаются до универсальных fallback-правил.</p>{error&&<div className="error">{error}</div>}<button>Сохранить снимок</button></form></Modal>}{instantiating&&<Modal title="Создать workflow из шаблона" onClose={()=>setInstantiating(null)}><form className="form" onSubmit={wrap(instantiate)}><p className="muted">Оригинал «{instantiating.name}» останется неизменным.</p><label>Проект<select name="project_id" value={instantiationProjectId} onChange={event=>setInstantiationProjectId(event.target.value)} required>{projects.data?.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</select></label><label>Источник<select name="source_id" required><option value="">Выберите источник</option>{sources.data?.filter(source=>source.project_id===instantiationProjectId).map(source=><option key={source.id} value={source.id}>{source.name}</option>)}</select></label><label>Dataset<select name="dataset_id" required><option value="">Выберите dataset</option>{datasets.data?.filter(dataset=>dataset.project_id===instantiationProjectId).map(dataset=><option key={dataset.id} value={dataset.id}>{dataset.name}</option>)}</select></label><label>Название workflow<input name="name" defaultValue={`${instantiating.name} — копия`}/></label>{error&&<div className="error">{error}</div>}<button>Создать копию</button></form></Modal>}{editing&&<Modal title="Настройки шаблона" onClose={()=>setEditing(null)}><form className="form" onSubmit={wrap(updateTemplate)}><label>Название<input name="name" defaultValue={editing.name} required/></label><label>Описание<textarea name="description" defaultValue={editing.description}/></label><label>Теги через запятую<input name="tags" defaultValue={(editing.tags||[]).join(', ')}/></label>{error&&<div className="error">{error}</div>}<button>Сохранить</button></form></Modal>}</>;
}

export function RunsPage(){
  const qc=useQueryClient();const query=useQuery({queryKey:['runs'],queryFn:()=>api<any[]>('/runs'),refetchInterval:5000});const workflows=useQuery({queryKey:['workflows'],queryFn:()=>api<any[]>('/workflows')});const [selected,setSelected]=useState<any>(null);const [loading,setLoading]=useState(false);
  async function open(row:any){setLoading(true);try{setSelected(await api(`/runs/${row.id}`))}finally{setLoading(false)}}
  async function refreshSelected(id:string){setSelected(await api(`/runs/${id}`));await qc.invalidateQueries({queryKey:['runs']})}
  const workflowNames=Object.fromEntries((workflows.data||[]).map(item=>[item.id,item.name]));
  const runs=(query.data||[]).map(run=>({...run,workflow_name:workflowNames[run.workflow_id]||run.workflow_id}));
  return <><Header title="Запуски"/><div className="panel">{query.isLoading?<Loading/>:<Table rows={runs} columns={['status','workflow_name','created_at','started_at','finished_at']} onRowClick={open}/>}</div>{loading&&<Modal title="Запуск" onClose={()=>setLoading(false)}><Loading/></Modal>}{selected&&<Modal title={`Запуск ${selected.run.id}`} wide onClose={()=>setSelected(null)}><div className="inline spread"><div className="inline"><StatusBadge value={selected.run.status}/><span>{selected.run.created_at}</span></div><div className="inline">{['QUEUED','RUNNING'].includes(selected.run.status)&&<ConfirmButton className="danger" onConfirm={async()=>{await api(`/runs/${selected.run.id}/cancel`,{method:'POST'});await refreshSelected(selected.run.id)}}>Отменить</ConfirmButton>}<button className="secondary" onClick={async()=>{const retry=await api<any>(`/runs/${selected.run.id}/retry`,{method:'POST'});await refreshSelected(retry.id)}}>Повторить</button></div></div>{selected.run.error_json&&Object.keys(selected.run.error_json).length>0&&<JsonView value={selected.run.error_json}/>}<h3>Узлы</h3>{selected.nodes.map((node:any)=><details key={node.id} className="node-run"><summary><StatusBadge value={node.status}/> {node.node_type} · {node.duration_ms} ms</summary><div className="diff"><JsonView value={node.input}/><JsonView value={node.output}/></div></details>)}<h3>Artifacts</h3><div className="artifact-list">{(selected.artifacts||[]).map((artifact:any)=><button className="secondary" key={artifact.id} onClick={async()=>{const blob=await api<Blob>(`/runs/artifacts/${artifact.id}/download`);const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=artifact.metadata?.filename||`artifact-${artifact.id}`;link.click();URL.revokeObjectURL(link.href)}}>{artifact.metadata?.kind||artifact.content_type} · {artifact.metadata?.filename||artifact.sha256.slice(0,12)}</button>)}</div><h3>Итог</h3><JsonView value={selected.run.output_json}/></Modal>}</>;
}

export function ReviewPage(){
  const qc=useQueryClient();const query=useQuery({queryKey:['review'],queryFn:()=>api<any[]>('/review')});const [editing,setEditing]=useState<any>(null);const [corrected,setCorrected]=useState('');
  if(query.error)return <ErrorPanel error={query.error}/>;
  async function act(id:string,action:string,payload:any={comment:''}){await api(`/review/${id}/${action}`,{method:'POST',body:JSON.stringify(payload)});await qc.invalidateQueries({queryKey:['review']})}
  return <><Header title="Проверка данных"/><div className="review-grid">{query.data?.map(task=>{const sampled=task.reason==='SAMPLED_RECORD';return <div className="panel" key={task.id}><div className="inline spread"><div><StatusBadge value={task.status}/><h3>{sampled?'Контрольная выборка':task.reason}</h3>{sampled&&<p className="muted">Сверьте значения с raw-страницей или ссылкой источника. Подтверждение не меняет запись.</p>}</div><span className="muted">{task.created_at}</span></div>{!sampled&&<div className="diff"><div><h4>Было</h4><JsonView value={task.old_data}/></div><div><h4>Стало</h4><JsonView value={task.new_data}/></div></div>}<details open={sampled}><summary>Данные и evidence</summary><JsonView value={sampled?task.new_data:task.evidence}/>{sampled&&<JsonView value={task.evidence}/>}</details><div className="inline"><button onClick={()=>act(task.id,'approve')}>{sampled?'Сверено':'Подтвердить'}</button><button className="secondary" onClick={()=>{setEditing(task);setCorrected(JSON.stringify(task.new_data,null,2))}}>Исправить</button><button className="danger" onClick={()=>act(task.id,'reject')}>{sampled?'Не совпадает':'Отклонить'}</button></div></div>})}</div>{!query.data?.length&&<div className="panel empty">Очередь проверки пуста</div>}{editing&&<Modal title="Исправление записи" wide onClose={()=>setEditing(null)}><textarea className="code-input large" value={corrected} onChange={event=>setCorrected(event.target.value)}/><button onClick={async()=>{await act(editing.id,'correct',{comment:'Исправлено оператором',corrected_data:JSON.parse(corrected)});setEditing(null)}}>Сохранить исправление</button></Modal>}</>;
}

export function SchemasPage(){
  const qc=useQueryClient();const query=useQuery({queryKey:['schemas'],queryFn:()=>api<any[]>('/schemas')});const projects=useQuery({queryKey:['projects'],queryFn:()=>api<any[]>('/projects')});const [open,setOpen]=useState(false);const [fields,setFields]=useState<any[]>([{name:'title',type:'string',required:true},{name:'source_url',type:'string',required:false}]);
  async function create(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);const properties=Object.fromEntries(fields.map(field=>[field.name,{type:field.type==='number'?'number':field.type==='integer'?'integer':field.type==='boolean'?'boolean':'string'}]));const schema={type:'object',properties,required:fields.filter(field=>field.required).map(field=>field.name)};await api('/schemas',{method:'POST',body:JSON.stringify({project_id:form.get('project_id'),name:form.get('name'),description:form.get('description'),schema_json:schema})});setOpen(false);await qc.invalidateQueries({queryKey:['schemas']})}
  return <><Header title="Схемы данных" actions={<button onClick={()=>setOpen(true)}>Создать схему</button>}/><div className="panel"><Table rows={query.data||[]} columns={['name','description','version','published']}/></div>{open&&<Modal title="Конструктор схемы" wide onClose={()=>setOpen(false)}><form className="form" onSubmit={create}><div className="split"><label>Проект<select name="project_id" required>{projects.data?.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</select></label><label>Название<input name="name" required/></label></div><label>Описание<textarea name="description"/></label><div className="editor-list"><div className="editor-list-head"><strong>Поля</strong><button type="button" className="secondary small" onClick={()=>setFields([...fields,{name:'field',type:'string',required:false}])}>+ Поле</button></div>{fields.map((field,index)=><div className="editor-row" key={index}><input value={field.name} onChange={event=>setFields(fields.map((item,i)=>i===index?{...item,name:event.target.value}:item))}/><select value={field.type} onChange={event=>setFields(fields.map((item,i)=>i===index?{...item,type:event.target.value}:item))}><option>string</option><option>number</option><option>integer</option><option>boolean</option></select><label className="checkbox inline-check"><input type="checkbox" checked={field.required} onChange={event=>setFields(fields.map((item,i)=>i===index?{...item,required:event.target.checked}:item))}/><span>required</span></label><button type="button" className="danger small" onClick={()=>setFields(fields.filter((_,i)=>i!==index))}>×</button></div>)}</div><button>Создать схему</button></form></Modal>}</>;
}

export function PromptsPage(){
  const qc=useQueryClient();const query=useQuery({queryKey:['prompts'],queryFn:()=>api<any[]>('/prompts')});const projects=useQuery({queryKey:['projects'],queryFn:()=>api<any[]>('/projects')});const models=useQuery({queryKey:['ai-models'],queryFn:()=>api<any[]>('/ai-models')});const [open,setOpen]=useState(false);const [test,setTest]=useState<any>(null);const [testContent,setTestContent]=useState('');const [testResult,setTestResult]=useState<any>(null);
  async function create(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);await api('/prompts',{method:'POST',body:JSON.stringify({project_id:form.get('project_id'),name:form.get('name'),provider:form.get('provider'),model:form.get('model'),system_prompt:form.get('system_prompt'),user_prompt:form.get('user_prompt'),response_schema:{},settings:{temperature:0,json_mode:true}})});setOpen(false);await qc.invalidateQueries({queryKey:['prompts']})}
  async function runTest(){setTestResult(await api(`/prompts/${test.id}/test`,{method:'POST',body:JSON.stringify({content:testContent,variables:{}})}))}
  const choices=(models.data||[]).flatMap(item=>item.models.map((model:string)=>({provider:item.provider,model})));
  return <><Header title="AI-модели и промпты" actions={<button onClick={()=>setOpen(true)}>Создать промпт</button>}/><div className="panel"><div className="table-wrap"><table><thead><tr><th>Название</th><th>Provider</th><th>Модель</th><th>Версия</th><th></th></tr></thead><tbody>{query.data?.map(prompt=><tr key={prompt.id}><td>{prompt.name}</td><td>{prompt.provider}</td><td>{prompt.model}</td><td>{prompt.version}</td><td><button onClick={()=>{setTest(prompt);setTestResult(null)}}>Playground</button></td></tr>)}</tbody></table></div></div>{open&&<Modal title="Новый промпт" wide onClose={()=>setOpen(false)}><form className="form" onSubmit={create}><div className="split"><label>Проект<select name="project_id">{projects.data?.map(project=><option key={project.id} value={project.id}>{project.name}</option>)}</select></label><label>Название<input name="name" required/></label><label>Provider<select name="provider">{[...new Set(choices.map(item=>item.provider))].map(item=><option key={item}>{item}</option>)}<option value="mock">mock</option></select></label><label>Модель<select name="model">{choices.map(item=><option key={`${item.provider}:${item.model}`} value={item.model}>{item.provider}: {item.model}</option>)}<option value="mock">mock</option></select></label></div><label>System prompt<textarea name="system_prompt" defaultValue="Верни только JSON по указанной схеме."/></label><label>User prompt<textarea name="user_prompt" defaultValue={'{{content}}'}/></label><button>Создать</button></form></Modal>}{test&&<Modal title={`Playground: ${test.name}`} wide onClose={()=>setTest(null)}><div className="split"><div className="form"><label>Контент<textarea className="large" value={testContent} onChange={event=>setTestContent(event.target.value)}/></label><button onClick={runTest}>Запустить</button></div><JsonView value={testResult||{}}/></div></Modal>}</>;
}

export function DataPage(){
  const qc=useQueryClient();const datasets=useQuery({queryKey:['datasets'],queryFn:()=>api<any[]>('/datasets')});const projects=useQuery({queryKey:['projects'],queryFn:()=>api<any[]>('/projects')});const schemas=useQuery({queryKey:['schemas'],queryFn:()=>api<any[]>('/schemas')});
  const [selected,setSelected]=useState('');const [view,setView]=useState<'all'|'approved'>('all');const [offset,setOffset]=useState(0);const [editing,setEditing]=useState<any>(null);const [history,setHistory]=useState<any>(null);const pageSize=100;
  useEffect(()=>{if(!selected&&datasets.data?.length)selectDataset(datasets.data[0].id)},[datasets.data,selected]);
  const summary=useQuery({queryKey:['dataset-summary',selected],queryFn:()=>api<any>(`/datasets/${selected}/summary`),enabled:!!selected});
  const records=useQuery({queryKey:['records',selected,offset,view],queryFn:()=>api<any>(`/datasets/${selected}/records?limit=${pageSize}&offset=${offset}&include_pending=${view==='all'}`),enabled:!!selected});
  const rows=(records.data?.items||[]).map((item:any)=>dataExplorerRow(item));
  const preferredColumns=['title','source_published_at','url','fetched_at','observed_at','review_status'];
  const availableColumns:string[]=[...new Set<string>(rows.flatMap((row:any):string[]=>Object.keys(row)))];
  const recordColumns=[...preferredColumns.filter(column=>availableColumns.includes(column)),...availableColumns.filter(column=>!preferredColumns.includes(column))].slice(0,12);
  async function download(format:string){if(!selected)return;const blob=await api<Blob>(`/exports?dataset_id=${encodeURIComponent(selected)}&format=${format}`,{method:'POST'});const dataset=datasets.data?.find(item=>item.id===selected);const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`${dataset?.slug||'export'}.${format}`;link.click();URL.revokeObjectURL(link.href)}
  const total=records.data?.total||0;
  function selectDataset(id:string){setSelected(id);setOffset(0)}
  async function acceptBaseline(){if(!selected)return;await api(`/datasets/${selected}/accept-baseline`,{method:'POST'});await Promise.all([qc.invalidateQueries({queryKey:['dataset-summary',selected]}),qc.invalidateQueries({queryKey:['records',selected]}),qc.invalidateQueries({queryKey:['review']})])}
  async function clearDataset(){if(!selected)return;await api(`/datasets/${selected}/records`,{method:'DELETE'});setOffset(0);await Promise.all([qc.invalidateQueries({queryKey:['dataset-summary',selected]}),qc.invalidateQueries({queryKey:['records',selected]}),qc.invalidateQueries({queryKey:['review']})])}
  async function deleteDataset(){if(!selected)return;await api(`/datasets/${selected}`,{method:'DELETE'});setSelected('');setOffset(0);await qc.invalidateQueries({queryKey:['datasets']})}
  async function saveDataset(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);const payload={project_id:form.get('project_id'),name:form.get('name'),slug:form.get('slug'),schema_id:form.get('schema_id')||null,natural_key_fields:String(form.get('natural_key_fields')).split(',').map(x=>x.trim()).filter(Boolean),review_policy:{new:form.get('review_new')==='on',changed:form.get('review_changed')==='on',confidence_below:Number(form.get('confidence')||0),sample_unchanged:Math.max(0,Number(form.get('sample_unchanged')||0))}};if(editing?.id)await api(`/datasets/${editing.id}`,{method:'PATCH',body:JSON.stringify(payload)});else await api('/datasets',{method:'POST',body:JSON.stringify(payload)});setEditing(null);await qc.invalidateQueries({queryKey:['datasets']})}
  return <>
    <Header title="Данные" subtitle="Dataset хранит текущие записи и историю версий; workflow добавляет новые ключи и обновляет существующие." actions={<div className="toolbar"><button onClick={()=>setEditing({})}>Создать dataset</button><select value={selected} onChange={event=>selectDataset(event.target.value)}>{datasets.data?.map(dataset=><option key={dataset.id} value={dataset.id}>{dataset.name}</option>)}</select><button disabled={!selected} onClick={()=>setEditing(datasets.data?.find(x=>x.id===selected))}>Настройки dataset</button><ConfirmButton className="secondary" onConfirm={clearDataset}>Очистить записи</ConfirmButton><ConfirmButton className="danger" onConfirm={deleteDataset}>Удалить dataset</ConfirmButton><button disabled={!selected||!summary.data?.approved} onClick={()=>download('xlsx')}>XLSX</button><button className="secondary" disabled={!selected||!summary.data?.approved} onClick={()=>download('csv')}>CSV</button><button className="secondary" disabled={!selected||!summary.data?.approved} onClick={()=>download('json')}>JSON</button></div>}/>
    <div className="panel">
      {selected ? <><div className="cards"><div className="card"><span>Подтверждено и доступно для экспорта</span><strong>{summary.data?.approved??0}</strong></div><div className="card"><span>Собрано, ожидает первичной проверки</span><strong>{summary.data?.pending??0}</strong></div><div className="card"><span>Отклонено</span><strong>{summary.data?.rejected??0}</strong></div></div>{(summary.data?.pending_initial||0)>0&&<div className="help-box"><strong>В базе уже есть {summary.data.pending_initial} первичных записей.</strong><p>Они видны ниже, но пока не идут в XLSX/API. После выборочной сверки исходных страниц можно принять базовый срез: это подтвердит только первые версии; будущие изменения всё равно останутся в «Проверка данных».</p><ConfirmButton onConfirm={acceptBaseline}>Принять базовый срез ({summary.data.pending_initial})</ConfirmButton></div>}<div className="tabs"><button className={view==='all'?'active secondary':'secondary'} onClick={()=>{setView('all');setOffset(0)}}>Все собранные ({(summary.data?.approved||0)+(summary.data?.pending||0)})</button><button className={view==='approved'?'active secondary':'secondary'} onClick={()=>{setView('approved');setOffset(0)}}>Подтверждённые — экспорт ({summary.data?.approved||0})</button></div><Table rows={rows} columns={recordColumns} onRowClick={row=>setHistory(row)} empty={view==='all'?'Собранных записей пока нет':'Нет подтверждённых записей: посмотрите «Все собранные» или примите базовый срез после проверки.'}/><div className="pagination"><span>{total?`${offset+1}–${Math.min(offset+pageSize,total)} из ${total}`:'Записей нет'}</span><button className="secondary" disabled={offset===0} onClick={()=>setOffset(Math.max(0,offset-pageSize))}>Назад</button><button className="secondary" disabled={offset+pageSize>=total} onClick={()=>setOffset(offset+pageSize)}>Вперёд</button></div></> : <Table rows={datasets.data||[]} columns={['name','slug','project_id','natural_key_fields']} onRowClick={row=>selectDataset(row.id)}/>}
    </div>
    {editing&&<Modal title={editing.id?'Редактировать dataset':'Создать dataset'} onClose={()=>setEditing(null)}><form className="form" onSubmit={saveDataset}><label>Проект<select name="project_id" defaultValue={editing.project_id} required>{projects.data?.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Название<input name="name" defaultValue={editing.name} required/></label><label>Slug<input name="slug" defaultValue={editing.slug} required pattern="[a-z0-9-]+"/></label><label>Схема<select name="schema_id" defaultValue={editing.schema_id||''}><option value="">Без схемы</option>{schemas.data?.filter(x=>!editing.project_id||x.project_id===editing.project_id).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Natural key<input name="natural_key_fields" defaultValue={(editing.natural_key_fields||[]).join(', ')}/></label><label className="checkbox"><input name="review_new" type="checkbox" defaultChecked={editing.review_policy?.new}/><span>Проверять новые</span></label><label className="checkbox"><input name="review_changed" type="checkbox" defaultChecked={editing.review_policy?.changed}/><span>Проверять изменения</span></label><label>Confidence threshold<input name="confidence" type="number" step=".05" min="0" max="1" defaultValue={editing.review_policy?.confidence_below??0}/></label><label>Контрольная выборка неизменных записей за запуск<input name="sample_unchanged" type="number" min="0" step="1" defaultValue={editing.review_policy?.sample_unchanged??0}/></label><p className="muted">0 — отключено. Выборка создаёт задачи на сверку с исходной страницей и не блокирует экспорт.</p><button>Сохранить</button></form></Modal>}
    {history&&<RecordHistory record={history} onClose={()=>setHistory(null)}/>}
  </>;
}

function dataExplorerRow(item:any){
  return {...(item.data||{}),...(item.timestamps||{}),record_id:item.id,natural_key:item.natural_key,confidence:item.confidence,review_status:item.review_status,updated_at:item.updated_at};
}

function RecordHistory({record,onClose}:{record:any;onClose:()=>void}){const query=useQuery({queryKey:['record-history',record.record_id],queryFn:()=>api<any[]>(`/records/${record.record_id}/history`)});return <Modal title="История записи" wide onClose={onClose}>{query.isLoading?<Loading/>:<Table rows={query.data||[]}/>}</Modal>}

export function SchedulesPage(){
  const qc=useQueryClient();const query=useQuery({queryKey:['schedules'],queryFn:()=>api<any[]>('/schedules')});const workflows=useQuery({queryKey:['workflows'],queryFn:()=>api<any[]>('/workflows')});const [open,setOpen]=useState(false);
  async function create(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);await api('/schedules',{method:'POST',body:JSON.stringify({workflow_id:form.get('workflow_id'),name:form.get('name'),cron:form.get('cron'),timezone:form.get('timezone'),enabled:true})});setOpen(false);await qc.invalidateQueries({queryKey:['schedules']})}
  const workflowNames=Object.fromEntries((workflows.data||[]).map(item=>[item.id,item.name]));
  const schedules=(query.data||[]).map(schedule=>({...schedule,workflow_name:workflowNames[schedule.workflow_id]||schedule.workflow_id}));
  return <><Header title="Расписания" actions={<button onClick={()=>setOpen(true)}>Создать расписание</button>}/><div className="panel"><Table rows={schedules} columns={['name','workflow_name','cron','timezone','enabled','created_at']}/></div>{open&&<Modal title="Новое расписание" onClose={()=>setOpen(false)}><form className="form" onSubmit={create}><label>Workflow<select name="workflow_id">{workflows.data?.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Название<input name="name" required/></label><label>Cron<input name="cron" defaultValue="0 8 * * 1" required/></label><label>Часовой пояс<input name="timezone" defaultValue="Europe/Minsk"/></label><button>Создать</button></form></Modal>}</>;
}

export function SettingsPage(){
  const qc=useQueryClient();const [tab,setTab]=useState<'connections'|'providers'|'browser'|'secrets'>('providers');const [open,setOpen]=useState(false);
  const connections=useQuery({queryKey:['connections'],queryFn:()=>api<any[]>('/connections'),enabled:tab==='connections'});
  const providers=useQuery({queryKey:['providers'],queryFn:()=>api<any[]>('/ai-providers'),enabled:tab==='providers'});
  const browsers=useQuery({queryKey:['browser-profiles'],queryFn:()=>api<any[]>('/browser-profiles'),enabled:tab==='browser'});
  const secrets=useQuery({queryKey:['secrets'],queryFn:()=>api<any[]>('/secrets'),enabled:tab==='secrets'});
  const data=tab==='connections'?connections.data:tab==='providers'?providers.data:tab==='browser'?browsers.data:secrets.data;
  async function create(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);if(tab==='providers')await api('/ai-providers',{method:'POST',body:JSON.stringify({provider_name:form.get('name'),provider_type:'OPENAI_COMPATIBLE',base_url:form.get('base_url'),api_key:form.get('secret'),default_model:form.get('model'),enabled:true})});if(tab==='secrets')await api('/secrets',{method:'POST',body:JSON.stringify({name:form.get('name'),value:form.get('secret')})});if(tab==='browser')await api('/browser-profiles',{method:'POST',body:JSON.stringify({name:form.get('name'),browser:'chromium',viewport:{width:1440,height:900},locale:'ru-RU',timezone:'Europe/Minsk',storage_state:form.get('secret')||'',enabled:true})});if(tab==='connections')await api('/connections',{method:'POST',body:JSON.stringify({name:form.get('name'),engine:form.get('engine'),host:form.get('host'),port:Number(form.get('port')),database:form.get('database'),username:form.get('username'),password:form.get('secret'),ssl_mode:'prefer',schema_name:'public',enabled:true})});setOpen(false);await qc.invalidateQueries({queryKey:[tab==='providers'?'providers':tab==='browser'?'browser-profiles':tab]})}
  return <><Header title="Подключения и настройки" actions={<button onClick={()=>setOpen(true)}>Добавить</button>}/><div className="tabs"><button className={tab==='providers'?'active secondary':'secondary'} onClick={()=>setTab('providers')}>AI providers</button><button className={tab==='connections'?'active secondary':'secondary'} onClick={()=>setTab('connections')}>Базы данных</button><button className={tab==='browser'?'active secondary':'secondary'} onClick={()=>setTab('browser')}>Browser profiles</button><button className={tab==='secrets'?'active secondary':'secondary'} onClick={()=>setTab('secrets')}>Секреты</button></div><div className="panel"><Table rows={data||[]}/></div>{open&&<Modal title="Новое подключение" onClose={()=>setOpen(false)}><form className="form" onSubmit={create}><label>Название<input name="name" required/></label>{tab==='providers'&&<><label>Base URL<input name="base_url" defaultValue="https://api.deepseek.com"/></label><label>Модель<input name="model" defaultValue="deepseek-chat"/></label></>}{tab==='connections'&&<><label>Engine<select name="engine"><option value="postgresql">PostgreSQL</option><option value="mysql">MySQL</option><option value="sqlite">SQLite</option></select></label><label>Host<input name="host"/></label><label>Port<input name="port" type="number" defaultValue="5432"/></label><label>Database<input name="database"/></label><label>Username<input name="username"/></label></>}<label>{tab==='browser'?'Storage state JSON':tab==='secrets'?'Значение':'API key / пароль'}<textarea name="secret" required={tab==='secrets'}/></label><button>Сохранить</button></form></Modal>}</>;
}

export function UsersPage(){
  const qc=useQueryClient();const query=useQuery({queryKey:['users'],queryFn:()=>api<any[]>('/users')});const [open,setOpen]=useState(false);
  async function create(event:FormEvent<HTMLFormElement>){event.preventDefault();const form=new FormData(event.currentTarget);await api('/users',{method:'POST',body:JSON.stringify({email:form.get('email'),password:form.get('password'),full_name:form.get('full_name'),roles:[form.get('role')]})});setOpen(false);await qc.invalidateQueries({queryKey:['users']})}
  return <><Header title="Пользователи" actions={<button onClick={()=>setOpen(true)}>Добавить пользователя</button>}/><div className="panel"><Table rows={query.data||[]} columns={['email','full_name','roles','is_active','created_at']}/></div>{open&&<Modal title="Новый пользователь" onClose={()=>setOpen(false)}><form className="form" onSubmit={create}><label>Email<input type="email" name="email" required/></label><label>Имя<input name="full_name"/></label><label>Пароль<input type="password" name="password" minLength={8} required/></label><label>Роль<select name="role"><option>DEVELOPER</option><option>OPERATOR</option><option>VIEWER</option><option>ADMINISTRATOR</option></select></label><button>Создать</button></form></Modal>}</>;
}

export function AuditPage(){const query=useQuery({queryKey:['audit'],queryFn:()=>api<any[]>('/audit')});return <><Header title="Audit log"/><div className="panel"><Table rows={query.data||[]} columns={['action','entity_type','entity_id','actor_id','created_at']}/></div></>}

export function ExportsPage(){return <><Header title="Экспорт"/><div className="panel"><p>Экспорт выполняется из раздела «Данные» и узлом Export File внутри workflow. Поддержаны XLSX, CSV и JSON.</p></div></>}

export function PlaceholderPage(){return <><Header title="Раздел"/><div className="panel empty">Раздел не найден.</div></>}
